import glob,json,ctypes,os,numpy as np,onnxruntime as ort
r={"node":os.environ["NODE_NAME"],"gpu_device_paths":glob.glob("/dev/nvidia*"),"ort_available_providers":ort.get_available_providers()}
try:
 lib=ctypes.CDLL("libcuda.so.1");r["cuda_driver_library"]=True;r["cuInit_result"]=lib.cuInit(0)
except OSError as e:r["cuda_driver_library"]=False;r["cuda_error"]=str(e)
o=ort.SessionOptions();o.intra_op_num_threads=1;o.inter_op_num_threads=1
s=ort.InferenceSession("/opt/model/yolox_tiny.onnx",sess_options=o,providers=["CPUExecutionProvider"]);s.disable_fallback()
a=s.get_inputs()[0];y=s.run(None,{a.name:np.zeros((1,3,416,416),dtype=np.float32)})
r.update(cpu_inference_succeeded=True,actual_providers=s.get_providers(),output_shapes=[list(v.shape) for v in y])
print(json.dumps(r),flush=True)
